// =========================================================================
// R4. GLOBAL IMAGE RESOLUTION ENGINE - RESOLVE BASE64 DATA URLS
// =========================================================================
function resolveImgUrl(url) {
  if (!url) return '';
  try { url = decodeURIComponent(url); } catch (e) {}
  url = url.split(/[?#]/)[0];
  if (typeof window !== 'undefined' && window.__EMBEDDED_MUSEUM_IMAGES__) {
    const store = window.__EMBEDDED_MUSEUM_IMAGES__;
    if (store[url]) return store[url];
    if (store['./' + url]) return store['./' + url];
    const stripped = url.replace(/^\.\//, '');
    if (store[stripped]) return store[stripped];
    const pubStripped = stripped.replace(/^public\//, '');
    if (store[pubStripped]) return store[pubStripped];
    if (store['public/' + pubStripped]) return store['public/' + pubStripped];
    if (store['./public/' + pubStripped]) return store['./public/' + pubStripped];
    const filename = url.substring(url.lastIndexOf('/') + 1);
    for (const k in store) {
      if (k.endsWith(filename) || k.includes(filename)) return store[k];
    }
  }
  return url;
}
if (typeof window !== 'undefined') {
  window.resolveImgUrl = resolveImgUrl;
}

